// Differential checks of TcoMc91.js against Lean, generated by leanscript --check
import * as M from "./TcoMc91.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("mc91(0n)", () => M.mc91(0n), "91", false);
check("mc91(1n)", () => M.mc91(1n), "91", false);
check("mc91(2n)", () => M.mc91(2n), "91", false);
check("mc91(5n)", () => M.mc91(5n), "91", false);
check("mc91(13n)", () => M.mc91(13n), "91", false);
check("mc91Loop(0n, 0n)", () => M.mc91Loop(0n, 0n), "0", false);
check("mc91Loop(0n, 2n)", () => M.mc91Loop(0n, 2n), "2", false);
check("mc91Loop(1n, 1n)", () => M.mc91Loop(1n, 1n), "91", false);
check("mc91Loop(2n, 0n)", () => M.mc91Loop(2n, 0n), "91", false);
check("mc91Loop(0n, 13n)", () => M.mc91Loop(0n, 13n), "13", false);
check("mc91Loop(1n, 5n)", () => M.mc91Loop(1n, 5n), "91", false);
check("mc91Loop(2n, 2n)", () => M.mc91Loop(2n, 2n), "91", false);
check("mc91Loop(5n, 1n)", () => M.mc91Loop(5n, 1n), "91", false);
check("mc91Loop(13n, 0n)", () => M.mc91Loop(13n, 0n), "91", false);
check("mc91Loop(2n, 13n)", () => M.mc91Loop(2n, 13n), "91", false);
check("mc91Loop(5n, 5n)", () => M.mc91Loop(5n, 5n), "91", false);
check("mc91Loop(13n, 2n)", () => M.mc91Loop(13n, 2n), "91", false);
check("mc91Loop(13n, 13n)", () => M.mc91Loop(13n, 13n), "91", false);
check("mc91TR(0n)", () => M.mc91TR(0n), "91", false);
check("mc91TR(1n)", () => M.mc91TR(1n), "91", false);
check("mc91TR(2n)", () => M.mc91TR(2n), "91", false);
check("mc91TR(5n)", () => M.mc91TR(5n), "91", false);
check("mc91TR(13n)", () => M.mc91TR(13n), "91", false);

console.log(`TcoMc91.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
